<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { HelpPanelContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: HelpPanelContract & { openerId?:string; hideOpener?:boolean; hideTopicTriggers?:boolean } = $props();
import PanelShell from './PanelShell.svelte';import {restoreFocus} from './modal-state.js';let narrow=$state(untrack(()=>typeof matchMedia==='function'&&matchMedia('(max-width:767px)').matches));let initiating=$state<HTMLElement>();const open=control(()=>p.open,untrack(()=>p.defaultOpen),untrack(()=>!narrow),open=>p.onOpenChange?.({open}));const topic=control<string|null>(()=>p.selectedTopicId,untrack(()=>p.defaultSelectedTopicId),null,id=>p.onTopicChange?.({id}));const uid=$props.id();const openerId=$derived(p.openerId??`${uid}-opener`);onMount(()=>{const media=matchMedia('(max-width:767px)');const change=()=>narrow=media.matches;change();media.addEventListener('change',change);return()=>media.removeEventListener('change',change);});async function select(id:string,event:MouseEvent){initiating=event.currentTarget as HTMLElement;const alreadyOpen=open.value;topic.request(id);if(!alreadyOpen)open.request(true);await tick();if(alreadyOpen&&open.value&&topic.value===id)document.getElementById(uid)?.focus();}
</script>
{#if !p.hideOpener}<button id={openerId} type="button" {...owned('help-panel','opener')} aria-expanded={open.value} aria-controls={uid} onclick={event=>{initiating=event.currentTarget;open.request(true);}}>도움말 열기</button>{/if}{#if !p.hideTopicTriggers}{#each p.topics as item(item.id)}<button type="button" {...owned('help-panel','topic-trigger')} onclick={event=>select(item.id,event)}>{item.title} 도움말</button>{/each}{/if}<PanelShell id={uid} labelledby={`${uid}-title`} componentId="help-panel" states={narrow?'open modal':'open'} open={open.value} {narrow} title="도움말" returnFocusId={p.hideOpener?undefined:openerId} fallbackFocusId={p.fallbackFocusId} initiatingElement={initiating} onClose={()=>open.request(false)}><div {...owned('help-panel','header')}><h2 id={`${uid}-title`} {...owned('help-panel','title')}>도움말</h2><button type="button" {...owned('help-panel','close')} onclick={()=>open.request(false)}>도움말 닫기</button></div><div {...owned('help-panel','body')}>{#if topic.value}{#each p.topics.filter(x=>x.id===topic.value) as item(item.id)}<article><h3>{item.title}</h3><p>{item.content}</p><ul {...owned('help-panel','related')}>{#each item.relatedLinks as link}<li><a href={link.href} target="_blank" rel="noopener noreferrer">{link.label} (새 창)</a></li>{/each}</ul><button type="button" onclick={()=>topic.request(null)}>목록으로</button></article>{/each}{:else}<ul>{#each p.topics as item(item.id)}<li><button type="button" onclick={()=>{topic.request(item.id);document.getElementById(uid)?.focus();}}>{item.title}</button></li>{/each}</ul>{/if}</div></PanelShell>
